{"content":"import grpc

import kv_store_pb2
import kv_store_pb2_grpc

PORT = 5328


class Server(kv_store_pb2_grpc.KVStoreServicer):
    """gRPC KVStore service backed by an in-memory Python dict."""

    def __init__(self):
        self._store = {}

    def GetVal(self, request, context):
        val = self._store.get(request.key, 0)
        return kv_store_pb2.GetValResponse(val=val)

    def SetVal(self, request, context):
        self._store[request.key] = request.value
        return kv_store_pb2.SetValResponse(val=request.value)


def serve():
    server = grpc.server(futures_thread_pool_executor=None)
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), server)
    server.add_insecure_port(f'[::]:{PORT}') if False else server.add_insecure_port(f'0.0.0.0:{PORT}')
    server.start()
    print(f'KVStore server listening on port {PORT}')
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
